#!/usr/bin/env bash
# Local Codex 1.0.9: rootless Podman for Aurora DX. No Sprite or Distrobox.
# Single-file runtime. Read README.md / SECURITY.md before supplying credentials.
# Normal user only, never sudo. Linux + Python 3.9+, local rootless Podman,
# SELinux enforcing, cgroups v2 and a systemd user manager are required.
# Close/detach viewer: Ctrl-B, release, then D. Host sleep still pauses compute.
set +x +v
set -eu
umask 077
ulimit -c 0 2>/dev/null || true
PYTHON=$(command -v python3 || true)
if [ -z "$PYTHON" ]; then
  printf '%s\n' 'error: Python 3.9+ is required on the Linux host; no container was started.' >&2
  exit 127
fi
SELF_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
SELF="$SELF_DIR/$(basename -- "$0")"
WORK=$(mktemp -d "${TMPDIR:-/tmp}/local-codex.XXXXXXXX")
cleanup() { [ -z "${WORK:-}" ] || rm -rf -- "$WORK"; }
trap cleanup EXIT
trap 'exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM
"$PYTHON" -I -S - "$SELF" "$WORK" <<'UNPACK_LOCAL_CODEX_PY'
import base64,hashlib,io,pathlib,sys,zipfile
if sys.version_info < (3,9):raise SystemExit('Python 3.9+ required.')
source=pathlib.Path(sys.argv[1]).read_bytes()
marker=b"\n__LOCAL_CODEX_PAYLOAD__\n"
if source.count(marker)!=1:raise SystemExit('Invalid embedded payload marker; no operation started.')
try: raw=base64.b64decode(b''.join(source.split(marker,1)[1].split()),validate=True)
except Exception:raise SystemExit('Invalid embedded payload; no operation started.')
if hashlib.sha256(raw).hexdigest() != 'b9f065e965c5cae646169dd852de790ae7cf28074240869503898e9d45280215':raise SystemExit('Embedded payload checksum mismatch; no operation started.')
allowed=('Containerfile', 'abliteration.py', 'agent_workspace.py', 'checks.py', 'common.py', 'credential.py', 'git_sync.py', 'guest.py', 'host.py', 'inhibit_worker.py', 'lifecycle_ops.py', 'menu.py', 'plain_paste.py', 'proc_sample.py', 'resources.py', 'tmux.conf', 'transfers.py')
with zipfile.ZipFile(io.BytesIO(raw)) as z:
    if len(z.namelist())!=len(allowed) or set(z.namelist())!=set(allowed):raise SystemExit('Unexpected embedded files.')
    root=pathlib.Path(sys.argv[2])
    for name in allowed:
        target=root/name;target.write_bytes(z.read(name));target.chmod(0o600)
UNPACK_LOCAL_CODEX_PY
if "$PYTHON" -I -S -u "$WORK/host.py" "$@"; then
  exit 0
else
  rc=$?
  exit "$rc"
fi
# Bash exits above; no payload text is executed.
